document.getElementById('sideToggle').onclick=()=>{document.querySelector('.wrap').classList.toggle('side-open')};
document.getElementById('sideOverlay').onclick=()=>{document.querySelector('.wrap').classList.remove('side-open')};
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.wrap').classList.remove('side-open')});
